    { id=231, name="Gnomeregan", isRaid=false, minLevel=24,
      mapID=90, loreFDID=608241, bgFDID=608163, buttonFDID=608202,
      desc="Built deep within the mountains of Dun Morogh, the wondrous city of Gnomeregan was a testament to the gnomes' intelligence and industry. But when the capital was invaded by troggs, the gnomish high tinker was betrayed by his advisor Sicco Thermaplugg. As a result, Gnomeregan was irradiated, and most of its inhabitants slain. The surviving gnomes fled, vowing to return someday and retake their home.",
      encounters = {
        { id=7361, name="Grubbis", order=1,
          uiMapID=226, x=0.77868801355, y=0.67008197308, rootSection=4690,
          desc="The radioactive gas that flooded the city was meant to anger the troggs and kill the gnomes, and Thermaplugg's plan was brutally effective. One trogg, however, reacted oddly to the substance: Grubbis grew. And grew. It was a side effect that Sicco had not anticipated, but he's never been one to waste valuable (and dangerous) resources. This giant trogg now patrols the tunnels of Gnomeregan. His loyal basilisk pet, Chomper, helps Grubbis sniff out gas leaks, tasty fungi, and even tastier intruders.",
          creatures = { {display=6533, file=607628, name="Grubbis"} },
          loot = { {id=9445,pct=8.8} },
          sections = {
            { id=4690, title="Strike", parent=0, child=0, sib=6476, order=1, spell=0, icon="Interface\\icons\\ability_rogue_ambush", flags=0, cdisp=0,
              body="Grubbis inflicts Physical damage to his current target." },
            { id=6476, title="Chomper", parent=0, child=0, sib=0, order=2, spell=0, icon=0, flags=0, cdisp=4906,
              body="Chomper fights alongside Grubbis." },
          },
        },
        { id=7079, name="Viscous Fallout", order=2,
          uiMapID=227, x=0.75956302881, y=0.46516400576, rootSection=4691,
          desc="The formerly robust and elegantly complex waterways of Gnomeregan are now an irradiated mess filled with toxic slime. A lone water elemental who had dwelt in the gnomes' aquifer became trapped in the contamination, and the pollution corrupted its pure form. It currently wanders the halls of Gnomeregan in anger and agony, a liquid embodiment of the vile poison of Thermaplugg's betrayal.",
          creatures = { {display=5497, file=607808, name="Viscous Fallout"} },
          loot = { {id=9454,pct=60.8}, {id=9452,pct=18.8}, {id=9453,pct=17.5} },
          sections = {
            { id=4691, title="Toxic Volley", parent=0, child=0, sib=0, order=1, spell=0, icon="Interface\\icons\\spell_nature_corrosivebreath", flags=512, cdisp=0,
              body="Viscous Fallout unleashes a volley of toxin, inflicting 56 Nature damage to all players within $21687A1 yards and 7 Nature damage every $21687t2 seconds for $21687d." },
          },
        },
        { id=6235, name="Electrocutioner 6000", order=3,
          uiMapID=227, x=0.24316899478, y=0.68442600965, rootSection=4692,
          desc="Mekgineer Thermaplugg is not a patient gnome. Rather than putting his inventions through a battery of tests to determine their safety and effectiveness, he rushes them into the field and moves on to the next project. The Electrocutioner 6000 was his first attempt at harnessing electricity as a weapon via a super-charged mechano-tank. Lieutenant Tom \"Sizzlepants\" Crankle, the only soldier to survive piloting the Electrocutioner, is now something of a hero among the leper gnomes.",
          creatures = { {display=6915, file=607594, name="Electrocutioner 6000"} },
          loot = { {id=6893,pct=79.4}, {id=9448,pct=41.2}, {id=9447,pct=31.1}, {id=9446,pct=16.2} },
          sections = {
            { id=4692, title="Megavolt", parent=0, child=0, sib=4693, order=1, spell=0, icon="Interface\\icons\\spell_nature_chainlightning", flags=64, cdisp=0,
              body="Electrocutioner 6000 inflicts Nature damage to all players in front of him." },
            { id=4693, title="Shock", parent=0, child=0, sib=4694, order=2, spell=0, icon="Interface\\icons\\spell_nature_wispheal", flags=0, cdisp=0,
              body="Electrocutioner 6000 throws a bolt of lightning at his current target, inflicting $11084s1 Nature damage." },
            { id=4694, title="Chain Bolt", parent=0, child=0, sib=0, order=3, spell=0, icon="Interface\\icons\\spell_nature_chainlightning", flags=64, cdisp=0,
              body="Electrocutioner 6000 strikes his current target with a lightning bolt that arcs to $11085x1 nearby targets, inflicting $11085s1 Nature damage to each target." },
          },
        },
        { id=6229, name="Crowd Pummeler 9-60", order=4,
          uiMapID=228, x=0.43169400096, y=0.88319700956, rootSection=4670,
          desc="In Gnomeregan's heyday, inventors would compete for status by pitting their creations against one another. The mekgineer Oglethorpe Obnoticus built an unbeatable robot, and this earned him respect in the high tinker's court. Sicco Thermaplugg stole Obnoticus's blueprints and then made a giant version of the machine. He set his forgery loose, and the horrific results drove the ruling council to banish the innocent Obnoticus. The Crowd Pummeler 9-60 is still one of Thermaplugg's favorite (stolen) inventions.",
          creatures = { {display=6774, file=607572, name="Crowd Pummeler 9-60"} },
          loot = { {id=9450,pct=65.3}, {id=9449,pct=32.6} },
          sections = {
            { id=4670, title="Arcing Smash", parent=0, child=0, sib=4671, order=1, spell=0, icon="Interface\\icons\\ability_warrior_cleave", flags=0, cdisp=0,
              body="Crowd Pummeler 9-60 lashes out in a vicious arc, inflicting Physical damage to players in front of it." },
            { id=4671, title="Crowd Pummel", parent=0, child=0, sib=4672, order=2, spell=0, icon="Interface\\icons\\inv_gauntlets_04", flags=0, cdisp=0,
              body="Crowd Pummeler 9-60 pummels players within $10887A1 yards, inflicting Physical damage and interrupting spell casting for $10887d." },
            { id=4672, title="Trample", parent=0, child=0, sib=0, order=3, spell=0, icon="Interface\\icons\\spell_nature_natureswrath", flags=0, cdisp=0,
              body="Crowd Pummeler 9-60 tramples players within $5568A1 yards, inflicting Physical damage." },
          },
        },
        { id=7800, name="Mekgineer Thermaplugg", order=5,
          uiMapID=229, x=0.31147500873, y=0.30327901244, rootSection=4702,
          desc="Murderer, traitor, and self-proclaimed king of the gnomes, the mekgineer Sicco Thermaplugg rules over the radioactive halls of Gnomeregan with a malfunctioning iron fist. His subjects are numerous, vicious, and insane enough to defend their crazed king against any intrusion from the upper world. It is Thermaplugg's madness that makes him so dangerous; he possesses the cunning to destroy everything around him, with no thought for his own life. There is a reason that even the monsters of Gnomeregan fear him.",
          creatures = { {display=6980, file=607714, name="Mekgineer Thermaplugg"} },
          loot = { {id=9461,pct=32.3}, {id=9458,pct=31.8}, {id=9459,pct=18.3}, {id=9492,pct=9.5}, {id=4411,pct=0.5}, {id=4415,pct=0.5}, {id=4413,pct=0.4}, {id=7742,pct=0.3}, {id=11828,pct=0} },
          sections = {
            { id=4702, title="Steam Blast", parent=0, child=0, sib=4703, order=1, spell=0, icon="Interface\\icons\\spell_fire_windsofwoe", flags=64, cdisp=0,
              body="Mekgineer Thermaplugg blasts his current target with steam, inflicting $93655s1 Fire damage and knocking them back." },
            { id=4703, title="Pound", parent=0, child=0, sib=4704, order=2, spell=0, icon="Interface\\icons\\ability_golemthunderclap", flags=0, cdisp=0,
              body="Mekgineer Thermaplugg pounds his current target, inflicting Physical damage and disorienting them for $74720d." },
            { id=4704, title="Welding Beam", parent=0, child=0, sib=4700, order=3, spell=0, icon="Interface\\icons\\spell_nature_lightningoverload", flags=64, cdisp=0,
              body="Mekgineer Thermplugg blasts his current target with a welding beam, inflicting 250 Nature damage over $52778d." },
            { id=4700, title="Walking Bomb", parent=0, child=4701, sib=0, order=4, spell=0, icon=0, flags=32, cdisp=6977,
              body="Mekgineer Thermaplugg activates a nearby bomb assembly, causing it to periodically release Walking Bombs that attack a random player. Walking Bombs will continue to spawn until the red switch on the side of the assembly is activated." },
            { id=4701, title="Detonate", parent=4700, child=0, sib=0, order=5, spell=0, icon="Interface\\icons\\spell_fire_selfdestruct", flags=0, cdisp=0,
              body="Walking Bomb detonates when it reaches its target, inflicting $11504s1 Fire damage to all players within $11504A1 yards." },
          },
        },
      },
    },
