            { id=4882, title="Amplify Flames", parent=0, child=0, sib=4883, order=3, spell=0, icon="Interface\\icons\\spell_fire_fireball", flags=0, cdisp=0,
              body="Galgann Firehammer increases the damage his current target takes from Fire for $9482d." },
