              body="Shadowforge Geologist calls down a pillar of flame, inflicting Fire damage to all players within $8814a1 yards of the targeted area and additional Fire damage every $8814t2 seconds for $8814d." },
            { id=4885, title="Flame Lash", parent=4883, child=0, sib=0, order=6, spell=0, icon="Interface\\icons\\spell_fire_fireball", flags=64, cdisp=0,
              body="Shadowforge Geologist burns a player, inflicting Fire damage and reducing their Fire resistance for $3356d. This effect stacks up to 3 times." },
          },
