    { id=232, name="Maraudon", isRaid=false, minLevel=40,
      mapID=349, loreFDID=608248, bgFDID=608170, buttonFDID=608209,
      desc="According to legend, Zaetar, son of Cenarius, and the earth elemental princess Theradras begot the barbaric centaur race. Shortly after the centaur's creation, the ruthless creatures murdered their father. The grief-stricken Theradras is said to have trapped her lover's spirit within Maraudon, corrupting the region. Now, vicious centaur ghosts and twisted elemental minions roam every corner of the sprawling caves.",
      encounters = {
        { id=13282, name="Noxxion", order=1,
          uiMapID=280, x=0.36202201247, y=0.0983607024, rootSection=4709,
          desc="Noxxion is a living embodiment of corruption. Theradras ordered her ally Lord Vyletongue to create this putrid elemental to be a powerful servant and a loyal pet to ease the princess's loneliness. Noxxion spreads its toxic essence into areas of Maraudon that have not yet withered under Theradras's malign influence.",
          creatures = { {display=11172, file=607728, name="Noxxion"} },
          loot = { {id=17746,pct=36.2}, {id=17744,pct=35.9}, {id=17745,pct=17.5} },
          sections = {
            { id=4709, title="Toxic Volley", parent=0, child=0, sib=4710, order=1, spell=0, icon="Interface\\icons\\spell_nature_corrosivebreath", flags=512, cdisp=0,
              body="Noxxion unleashes a volley of toxin, inflicting Nature damage instantly to all players within $21687A1 yards and additional Nature damage every $21687t2 seconds for $21687d." },
            { id=4710, title="Uppercut", parent=0, child=0, sib=4711, order=2, spell=0, icon="Interface\\icons\\inv_gauntlets_05", flags=0, cdisp=0,
              body="Noxxion uppercuts his current target, inflicting Physical damage and knocking them away." },
            { id=4711, title="Summon Noxxion Spawn", parent=0, child=4712, sib=0, order=3, spell=0, icon="Interface\\icons\\spell_nature_abolishmagic", flags=0, cdisp=0,
              body="Noxxion's body divides into 5 Noxxion Spawn, rendering him unable to fight for up to 20 seconds. Once all 5 Noxxion Spawn are killed, Noxxion regains his original form." },
            { id=4712, title="Noxxion Spawn", parent=4711, child=0, sib=0, order=4, spell=0, icon=0, flags=0, cdisp=5492,
              body="Noxxion Spawn split from Noxxion's main body." },
          },
        },
        { id=12258, name="Razorlash", order=2,
          uiMapID=280, x=0.16666699946, y=0.3442620039, rootSection=4713,
          desc="Razorlash was made to accompany Noxxion through Maraudon. In time, this new creation became one of the princess's most cherished servants. Razorlash constantly wanders the caves alongside Noxxion, using thorny tendrils to shred any untainted plant life it can find.",
          creatures = { {display=12389, file=607756, name="Razorlash"} },
          loot = { {id=17749,pct=24.7}, {id=17750,pct=24.2}, {id=17748,pct=24.0}, {id=17751,pct=23.8} },
          sections = {
            { id=4713, title="Puncture", parent=0, child=0, sib=4714, order=1, spell=0, icon="Interface\\icons\\ability_backstab", flags=0, cdisp=0,
              body="Razorlash punctures its current target, inflicting Physical damage every $15976t1 seconds for $15976d." },
            { id=4714, title="Thrash", parent=0, child=0, sib=4715, order=2, spell=0, icon="Interface\\icons\\ability_ghoulfrenzy", flags=0, cdisp=0,
              body="Razorlash thrashes its current target, attacking two additional times." },
            { id=4715, title="Cleave", parent=0, child=0, sib=0, order=3, spell=0, icon="Interface\\icons\\ability_warrior_cleave", flags=0, cdisp=0,
              body="Razorlash cleaves, inflicting Physical damage to its current target and their nearest allies, affecting up to $40504x1 targets." },
          },
        },
        { id=13601, name="Tinkerer Gizlock", order=3,
          uiMapID=280, x=0.50956302881, y=0.5307379961, rootSection=4721,
          desc="Tinkerer Gizlock and five other gem hunters snuck into Maraudon to mine its highly prized crystals. Their plan went horribly wrong when satyrs slaughtered everyone in the party save for Gizlock. The goblin, trapped within the caves and driven to the brink of madness, sees himself as the subterranean region's new ruler.",
          creatures = { {display=7125, file=607796, name="Tinkerer Gizlock"} },
          loot = { {id=17719,pct=33.1}, {id=17718,pct=32.8}, {id=17717,pct=32.8} },
          sections = {
