        { id=7271, name="Witch Doctor Zum'rah", order=2,
          uiMapID=219, x=0.44262298942, y=0.17622999847, rootSection=5011,
          desc="The powerful loa Bwonsamdi watches over the spirits of the Darkspear trolls, but many of the Sandfury tribe's fallen members are offered no such protection after death. These tortured spirits obey Zum'rah, a cruel witch doctor who uses his dark magic to force the city's dead into unending service.",
