        { id=9033, name="General Angerforge", order=10,
          uiMapID=243, x=0.36338800192, y=0.82376998663, rootSection=4508,
          desc="Through a lifetime of study, General Angerforge has become an expert on dwarven military history and tactics. He recently incurred Emperor Dagran Thaurissan's fury by writing a scathing treatise on his clan's failures in past conflicts. This political blunder aside, Angerforge is a Dark Iron to his core. He will bleed--and die, if necessary--to protect his people and his emperor.",
          creatures = { {display=8756, file=607610, name="General Angerforge"} },
          loot = { {id=11816,pct=29.1}, {id=11820,pct=28.8}, {id=11821,pct=11.3}, {id=11817,pct=8.3}, {id=11810,pct=5.6}, {id=11841,pct=0} },
