        { id=8983, name="Golem Lord Argelmach", order=11,
          uiMapID=243, x=0.36475399137, y=0.65163898468, rootSection=4501,
          desc="Argelmach's lifelong obsession with immortality drove him to forge enchanted constructs in his own image. Rumor has it that he has also dabbled in some form of black magic that would allow the golem lord's new creations to act as vessels for his spirit should his flesh-and-blood body be destroyed.",
          creatures = { {display=8759, file=607618, name="Golem Lord Argelmach"} },
          loot = { {id=11823,pct=37.2}, {id=11822,pct=36.8}, {id=11669,pct=9.5}, {id=11819,pct=8.9} },
          sections = {
            { id=4501, title="Chain Lightning", parent=0, child=0, sib=4502, order=1, spell=0, icon="Interface\\icons\\spell_nature_chainlightning", flags=0, cdisp=0,
              body="Golem Lord Argelmach inflicts Nature damage to a player.  Chain Lightning jumps to a nearby player within 15 yards and inflicts Nature damage again.  Chain Lightning will hit up to $15305x targets." },
            { id=4502, title="Shock", parent=0, child=0, sib=4503, order=2, spell=0, icon="Interface\\icons\\spell_nature_wispheal", flags=0, cdisp=0,
              body="Golem Lord Argelmach inflicts Nature damage to a player." },
            { id=4503, title="Lightning Shield", parent=0, child=0, sib=0, order=3, spell=0, icon="Interface\\icons\\spell_nature_lightningshield", flags=128, cdisp=0,
              body="Golem Lord Argelmach surrounds himself with $15507n balls of lightning.  There is a $15507h% chance that the Lightning Shield will retaliate against any attack players make. When retaliating, the Lightning Shield inflicts Nature damage and consumes one ball of lightning.  The Lightning Shield persists until all the balls of lightning are consumed." },
          },
        },
        { id=9537, name="Hurley Blackbreath", order=12,
          uiMapID=243, x=0.50566798449, y=0.70477801561, rootSection=4494,
          desc="To say Blackbreath is a regular at the Grim Guzzler would be something of an understatement. In over a decade, the mischievous drunkard has left the tavern only once to steal a top-secret recipe for Thunderbrew Lager. Blackbreath has occasionally sobered up enough to make the concoction himself, and he claims it grants unimaginable strength and courage.",
          creatures = { {display=8658, file=607650, name="Hurley Blackbreath"} },
          loot = { {id=12793,pct=29.5}, {id=18044,pct=23.9}, {id=22275,pct=23.0}, {id=18043,pct=20.4}, {id=18653,pct=16.9}, {id=11742,pct=13.8}, {id=11612,pct=12.4}, {id=12791,pct=10.2}, {id=2663,pct=9.0}, {id=2662,pct=8.5}, {id=11735,pct=7.6}, {id=11325,pct=1.6}, {id=11602,pct=0.2}, {id=18592,pct=0}, {id=13483,pct=0}, {id=15759,pct=0} },
