        { id=9019, name="Emperor Dagran Thaurissan", order=19,
          uiMapID=243, x=0.90983599424, y=0.11885199696, rootSection=4645,
          desc="Emperor Dagran Thaurissan rules alongside Princess Moira of the rival Bronzebeard clan. Debate rages over whether the emperor ensorcelled his bride or she willingly joined him. Whatever the truth, Thaurissan's continued presence bodes ill for the future of his clan. So long as he lives, the Dark Irons will remain pawns of Ragnaros, and a dire threat to kingdoms throughout Azeroth.",
          creatures = { {display=8807, file=607595, name="Emperor Dagran Thaurissan"} },
          loot = { {id=11931,pct=21.5}, {id=11924,pct=21.3}, {id=11930,pct=20.0}, {id=11928,pct=19.4}, {id=22207,pct=17.4}, {id=11934,pct=17.0}, {id=11932,pct=16.0}, {id=11815,pct=15.6}, {id=22204,pct=14.8}, {id=11933,pct=13.8}, {id=12033,pct=3.2}, {id=11684,pct=0.6} },
