    { id=237, name="The Temple of Atal'hakkar", isRaid=false, minLevel=50,
      mapID=109, loreFDID=608256, bgFDID=608178, buttonFDID=608217,
      desc="Thousands of years ago, the Gurubashi empire was plunged into a civil war by a powerful sect of priests, the Atal'ai, who sought to summon to Azeroth an avatar of their god of blood, Hakkar the Soulflayer. The Gurubashi people exiled the Atal'ai to the Swamp of Sorrows, where the priests built the Temple of Atal'Hakkar. Ysera, Aspect of the green dragonflight, sank the temple beneath the swamp and assigned wardens to ensure that the summoning rituals never be performed again.",
      encounters = {
        { id=8443, name="Avatar of Hakkar", order=1,
          uiMapID=220, x=0.24316899478, y=0.45901599526, rootSection=4903,
          desc="Hakkar was notorious for demanding sacrifices from his followers. Many millennia ago, he instructed the Atal'ai to bring forth his avatar, using blood ritually drained from living victims to feed him. The Atal'ai priests now seek to raise Hakkar's avatar with a modified version of this ritual, one that involves sacrificing green dragons. If the Atal'ai succeed, the re-emergence of Hakkar's avatar could spell doom for Azeroth.",
          creatures = { {display=8053, file=607548, name="Avatar of Hakkar"} },
          loot = { {id=10842,pct=30.3}, {id=10846,pct=30.2}, {id=10843,pct=28.5}, {id=10845,pct=26.5}, {id=10838,pct=14.3}, {id=10844,pct=14.1}, {id=12462,pct=0} },
          sections = {
            { id=4903, title="Cause Insanity", parent=0, child=0, sib=4904, order=1, spell=0, icon="Interface\\icons\\spell_shadow_shadowworddominate", flags=0, cdisp=0,
              body="The Avatar of Hakkar drives a player insane, causing them to attack their own allies for $12888d. Players driven insane will attack $12888s2% faster and move $12888s3% faster." },
            { id=4904, title="Curse of Tongues", parent=0, child=0, sib=4905, order=2, spell=0, icon="Interface\\icons\\spell_shadow_curseoftounges", flags=256, cdisp=0,
              body="The Avatar of Hakkar curses a player, reducing their casting speed by $12889s1% for $12889d." },
            { id=4905, title="Lash", parent=0, child=0, sib=0, order=3, spell=0, icon="Interface\\icons\\ability_criticalstrike", flags=0, cdisp=0,
              body="The Avatar of Hakkar lashes out at his current target, stunning them for $6607d. In addition, Lash has a 10% chance of disarming its target for $33126d." },
          },
        },
        { id=5710, name="Jammal'an the Prophet", order=2,
          uiMapID=220, x=0.76092898846, y=0.45901599526, rootSection=4934,
          desc="Jammal'an is the current leader of the Atal'ai, the extremist sect of priests who fanatically worship Hakkar. While in deep meditation, Jammal'an received instructions on how to resurrect Hakkar by using the blood of his draconic foes, the green dragonflight. Jammal'an and his undead bodyguard Ogom the Wretched stand ready to oppose any who would prevent Hakkar's return, though the prophet's actions may unleash upon Azeroth an even more terrible force: the Emerald Nightmare.",
          creatures = { {display=6708, file=607665, name="Jammal'an the Prophet"} },
          loot = { {id=10808,pct=29.6}, {id=10807,pct=27.2}, {id=10806,pct=27.0} },
          sections = {
            { id=4934, title="Healing Wave", parent=0, child=0, sib=4935, order=1, spell=0, icon="Interface\\icons\\spell_nature_magicimmunity", flags=0, cdisp=0,
              body="Jammal'an the Prophet heals an ally." },
            { id=4935, title="Flamestrike", parent=0, child=0, sib=4936, order=2, spell=0, icon="Interface\\icons\\spell_fire_selfdestruct", flags=0, cdisp=0,
              body="Jammal'an the Prophet calls down a pillar of flame, inflicting Fire damage to all players within $12468a1 yards of the targeted area and additional Fire damage every $12468t2 seconds for $12468d." },
            { id=4936, title="Earthgrab Totem", parent=0, child=0, sib=4937, order=3, spell=0, icon="Interface\\icons\\spell_nature_naturetouchdecay", flags=0, cdisp=0,
              body="Jammal'an the Prophet summons an Earthgrab Totem at his feet for $8376d. Earthgrab Totem immobilizes all players within $8377A1 yards every $8378t1 seconds." },
            { id=4937, title="Hex of Jammal'an", parent=0, child=0, sib=4938, order=4, spell=0, icon="Interface\\icons\\spell_totem_wardofdraining", flags=0, cdisp=0,
              body="Jammal'an the Prophet hexes a player, increasing their damage by $12480s2%, transforming them and causing them to attack their allies." },
            { id=4938, title="Ogom the Wretched", parent=0, child=4939, sib=0, order=5, spell=0, icon=0, flags=0, cdisp=6709,
              body="Ogom the Wretched joins Jammal'an the Prophet in battle." },
            { id=4939, title="Curse of Weakness", parent=4938, child=0, sib=4940, order=6, spell=0, icon="Interface\\icons\\spell_shadow_curseofmannoroth", flags=256, cdisp=0,
              body="Ogom the Wretched curses a player, reducing their Physical damage done." },
            { id=4940, title="Shadow Word: Pain", parent=4938, child=0, sib=4941, order=7, spell=0, icon="Interface\\icons\\spell_shadow_shadowwordpain", flags=128, cdisp=0,
              body="Ogom the Wretched utters a word of darkness, inflicting Shadow damage to a player every $11639t1 seconds for $11639d." },
            { id=4941, title="Shadow Bolt", parent=4938, child=0, sib=0, order=8, spell=0, icon="Interface\\icons\\spell_shadow_shadowbolt", flags=64, cdisp=0,
              body="Ogom the Wretched hurls a bolt of dark magic at a player, inflicting Shadow damage." },
          },
        },
        { id=5312, name="Wardens of the Dream", order=3,
          uiMapID=220, x=0.49915099144, y=0.87030899525, rootSection=6114,
          desc="Four promising young drakes accompanied Eranikus into the Temple of Atal'Hakkar, eager to prove themselves by serving a great and powerful wyrm. One by one, they were captured and tainted by the Emerald Nightmare, and they now wander the halls of the Sunken Temple, lashing out at all who intrude upon their waking dream.",
          creatures = { {display=7553, file=608311, name="Wardens of the Dream"} },
          sections = {
            { id=6114, title="The Wardens of the Dream", parent=0, child=4942, sib=0, order=1, spell=0, icon=0, flags=0, cdisp=0,
              body="Dreamscythe, Weaver, Morphaz and Hazzas defend the Shade of Eranikus with their lives." },
            { id=4942, title="Acid Breath", parent=6114, child=0, sib=4943, order=2, spell=0, icon="Interface\\icons\\spell_nature_acid_01", flags=0, cdisp=0,
              body="The Wardens of the Dream breath acid, inflicting Nature damage instantly and additional Nature damage every $12884t1 seconds for $12884d to all players in front of them." },
            { id=4943, title="Wing Flap", parent=6114, child=0, sib=0, order=3, spell=0, icon="Interface\\icons\\spell_nature_earthbind", flags=0, cdisp=0,
              body="The Wardens of the Dream thrash their wings, knocking all players in front of them backwards." },
          },
        },
        { id=5709, name="Shade of Eranikus", order=7,
          uiMapID=220, x=0.6707649827, y=0.87704902887, rootSection=4950,
          desc="Eranikus, former consort to Ysera the Dreamer, was sent to guard the ruins of Atal'Hakkar and prevent Hakkar's emergence. Once within the temple, he and his retinue were corrupted by its dark forces, and he became a shade, pulled between the realms of the Emerald Dream and the physical plane. Despite his corruption, Eranikus may still call upon his powers as a green dragon to spew corrosive acid at his enemies or trap them in a deep slumber.",
          creatures = { {display=7806, file=607768, name="Shade of Eranikus"} },
          loot = { {id=10454,pct=63.7}, {id=10829,pct=31.8}, {id=10833,pct=30.9}, {id=10835,pct=28.9}, {id=10836,pct=26.3}, {id=10828,pct=16.4}, {id=10837,pct=14.2}, {id=10847,pct=0.2} },
          sections = {
            { id=4950, title="Deep Slumber", parent=0, child=0, sib=4951, order=1, spell=0, icon="Interface\\icons\\spell_shadow_cripple", flags=128, cdisp=0,
              body="The Shade of Eranikus lulls a player into a deep sleep for $12890d, stunning them and making them invulnerable." },
            { id=4951, title="Thrash", parent=0, child=0, sib=4952, order=2, spell=0, icon="Interface\\icons\\ability_ghoulfrenzy", flags=0, cdisp=0,
              body="The Shade of Eranikus thrashes his current target, attacking $3391s1 additional times." },
            { id=4952, title="War Stomp", parent=0, child=0, sib=4953, order=3, spell=0, icon="Interface\\icons\\ability_bullrush", flags=0, cdisp=0,
              body="The Shade of Eranikus stomps, stunning all players within $11876A1 yards for $11876d." },
            { id=4953, title="Acid Breath", parent=0, child=0, sib=0, order=4, spell=0, icon="Interface\\icons\\spell_nature_acid_01", flags=0, cdisp=0,
              body="The Shade of Eranikus breaths acid, inflicting Nature damage instantly and additional Nature damage every $12891t1 seconds for $12891d to all players in front of him." },
          },
        },
