            { id=4531, title="Mortal Strike", parent=4529, child=0, sib=0, order=6, spell=0, icon="Interface\\icons\\ability_warrior_savageblow", flags=0, cdisp=0,
              body="War Master Voone inflicts Physical damage to his current target, reducing the effectiveness of their healing received by $16856s2% for $16856d." },
            { id=4534, title="Stage Three: The War Master", parent=0, child=4535, sib=0, order=7, spell=0, icon=0, flags=0, cdisp=0,
