            { id=4535, title="Snap Kick", parent=4534, child=0, sib=4536, order=8, spell=0, icon="Interface\\icons\\ability_kick", flags=0, cdisp=0,
              body="War Master Voone kicks his current target, inflicting Physical damage and stunning them for $15618d." },
            { id=4536, title="Uppercut", parent=4534, child=0, sib=4537, order=9, spell=0, icon="Interface\\icons\\inv_gauntlets_05", flags=0, cdisp=0,
              body="War Master Voone uppercuts his current target, inflicting Physical damage and knocking them away." },
            { id=4537, title="Pummel", parent=4534, child=0, sib=0, order=10, spell=0, icon="Interface\\icons\\inv_gauntlets_04", flags=0, cdisp=0,
              body="War Master Voone pummels a random player, inflicting Physical damage and interrupting spell casting for $15615d." },
          },
        },
        { id=10596, name="Mother Smolderweb", order=4,
          uiMapID=251, x=0.62073600292, y=0.7414150238, rootSection=4543,
          desc="Centuries ago, the Dark Iron dwarves dug into the lair of Mother Smolderweb, releasing the massive arachnid into the spire's halls. Her brood has continued to swell in number since that time, so much so that even Blackhand's forces fear traveling through Smolderweb's domain.",
          creatures = { {display=9929, file=607719, name="Mother Smolderweb"} },
