        { id=11487, name="Magister Kalendris", order=7,
          uiMapID=237, x=0.33879798651, y=0.45081999898, rootSection=4836,
          desc="When Prince Tortheldrin demanded the slaughter of the majority of his subjects, his most loyal lieutenants were tasked with executing his will. Magister Kalendris murdered many unsuspecting Shen'dralar without hesitation, but one of the doomed elves mortally wounded him during a destructive battle. Despite his demise, Kalendris's spirit still roams Dire Maul as a defender of Tortheldrin's rule.",
          creatures = { {display=14384, file=607703, name="Magister Kalendris"} },
          loot = { {id=18350,pct=25.2}, {id=18351,pct=23.4}, {id=18374,pct=19.9}, {id=18397,pct=19.4}, {id=18371,pct=8.7}, {id=22309,pct=0.4} },
