        { id=11486, name="Prince Tortheldrin", order=9,
          uiMapID=238, x=0.62295097113, y=0.2315569967, rootSection=4754,
          desc="After the Well of Eternity's destruction, Prince Tortheldrin maintained control over the surviving Shen'dralar by imprisoning a demon in the ruins of Eldre'Thalas and letting his subjects siphon its strength. The exposure to demonic power twisted Tortheldrin's mind, and when the creature faltered, the prince ordered the deaths of many of his vassals so only he and his most fanatical followers would be left to enjoy the corrupt energy.",
          creatures = { {display=11256, file=607745, name="Prince Tortheldrin"} },
