        { id=13280, name="Hydrospawn", order=2,
          uiMapID=240, x=0.53688502312, y=0.71516400576, rootSection=5004,
          desc="When the satyr Zevrim Thornhoof sought to control the elementals in Dire Maul, he focused on Hydrospawn, who calmly resided in the pool beneath his altar. As he performed his profane sacrificial rituals, the elemental grew agitated and restless, striking out at Thornhoof's demonic minions. As the years passed, Thornhoof used his victims' energies to whip Hydrospawn into unbridled fury, little by little binding its will to the satyr's commands.",
          creatures = { {display=5489, file=607653, name="Hydrospawn"} },
          loot = { {id=18305,pct=24.2}, {id=18307,pct=23.6}, {id=18322,pct=19.6}, {id=18317,pct=18.9}, {id=18324,pct=9.7}, {id=19268,pct=1.2} },
