              body="Hearthsinger Forresten lulls a player to sleep, stunning them for $16798d or until they take damage." },
            { id=4795, title="Demoralizing Shout", parent=0, child=0, sib=4796, order=2, spell=0, icon="Interface\\icons\\ability_warrior_warcry", flags=0, cdisp=0,
              body="Hearthsinger Forresten shouts, reducing the Stamina and primary stats of all players within $16244A1 yards by $16244s1% for $16244d." },
            { id=4796, title="Incorporeal Defense", parent=0, child=0, sib=4798, order=3, spell=0, icon="Interface\\icons\\spell_magearmor", flags=0, cdisp=0,
              body="Hearthsinger Forresten's chance to dodge attacks is increased by 50%." },
