    { id=1292, name="Stratholme - Service Entrance", isRaid=false, minLevel=60,
      mapID=329, loreFDID=608255, bgFDID=608177, buttonFDID=608216,
      desc="Stratholme was once the jewel of northern Lordaeron, but today it is remembered for its harrowing fall to ruin. It was here that Prince Arthas turned his back on the noble paladin Uther Lightbringer, slaughtering countless residents believed to be infected with the horrific plague of undeath. Ever since, cursed Stratholme has been marred by death, betrayal, and hopelessness.",
      encounters = {
        { id=10436, name="Baroness Anastari", order=0,
          uiMapID=318, x=0.74590200186, y=0.4692620039, rootSection=4841,
          desc="While she lived, Anastari took what she wanted, no matter the cost. Death has done little to change that. Her soul ripped from her body, Anastari became a banshee, and she has abandoned her love of material trinkets in favor of possessions of a far more sinister kind.",
          creatures = { {display=10698, file=607553, name="Baroness Anastari"} },
          loot = { {id=18730,pct=18.6}, {id=16704,pct=17.7}, {id=18728,pct=17.5}, {id=18729,pct=17.2}, {id=13534,pct=17.2}, {id=13539,pct=10.7}, {id=13535,pct=10.6}, {id=13537,pct=10.5}, {id=13538,pct=10.1}, {id=13514,pct=8.9} },
          sections = {
            { id=4841, title="Possess", parent=0, child=0, sib=4842, order=1, spell=0, icon="Interface\\icons\\spell_shadow_charm", flags=34, cdisp=0,
              body="Baroness Anastari takes control of a random player. Possess increases the target's maximum health by $17244s3% and damage dealt by $17246s1%, but reduces their healing received by $17246s3% and armor by $17246s4%. The target is controlled for $17244d or until they have reached 50% remaining health." },
            { id=4842, title="Banshee Wail", parent=0, child=0, sib=4843, order=2, spell=0, icon="Interface\\icons\\spell_shadow_shadowbolt", flags=68, cdisp=0,
