              body="Baroness Anastari silences all players within $18327A1 yards, preventing spell casting for $18327d." },
            { id=4844, title="Banshee Curse", parent=0, child=0, sib=0, order=4, spell=0, icon="Interface\\icons\\spell_nature_drowsy", flags=256, cdisp=0,
              body="Baroness Anastari curses all players within $16867A1 yards, reducing their chance to hit by $16867s1% for $16867d." },
