      body = "Kurinnaxx conjures sand traps beneath the raid that erupt when disturbed, inflicting heavy Nature damage and hurling players into the air." },
    { title = "Enrage", flags = 2048, spell = 0,
      body = "Over the course of the fight Kurinnaxx steadily enrages, increasing the damage he deals — he must be slain before it becomes lethal." },
  },
  [15341] = { -- General Rajaxx
    { title = "Summon the Army", flags = 32, spell = 0,
      body = "Rajaxx commands wave after wave of the Qiraji army, each led by a captain, to assault the raid before he himself enters the fray." },
    { title = "Thundercrack", flags = 128, spell = 8150,
      body = "Rajaxx unleashes a thundercrack, inflicting Nature damage and stunning all nearby players." },
    { title = "Thunderclap", flags = 128, spell = 8078,
      body = "Rajaxx slams the ground, inflicting Nature damage to nearby players and slowing their attack speed." },
  },
  [15340] = { -- Moam
    { title = "Drain Mana", flags = 32, spell = 25671,
      body = "Moam drains the mana from the raid's casters, converting it into arcane energy that builds toward a devastating release." },
    { title = "Arcane Eruption", flags = 32, spell = 25672,
      body = "Once charged with stolen mana, Moam erupts with arcane energy, inflicting heavy Arcane damage to the entire raid." },
    { title = "Summon Mana Fiends", flags = 32, spell = 0,
      body = "Moam summons Mana Fiends to drain the raid and turns to stone to recharge once fully energized." },
  },
  [15370] = { -- Buru the Gorger
    { title = "Full Speed", flags = 32, spell = 1557,
      body = "Buru fixates on a single player and pursues them at full speed, ignoring all others. The raid must kite him among his eggs." },
    { title = "Egg Explosion", flags = 32, spell = 0,
      body = "Buru takes greatly reduced damage until his eggs are destroyed. Each egg explodes violently when broken, weakening Buru but harming the raid." },
    { title = "Creeping Plague", flags = 0, spell = 20512,
      body = "Once his eggs are gone, Buru afflicts the raid with a creeping plague, inflicting escalating Nature damage over time." },
  },
  [15369] = { -- Ayamiss the Hunter
    { title = "Paralyze", flags = 32, spell = 25725,
      body = "Ayamiss paralyzes a random player and levitates them to the sacrificial altar, where her swarmers feed on them unless the raid intervenes." },
    { title = "Stinger Spray", flags = 0, spell = 25749,
      body = "Ayamiss sprays a volley of stingers, inflicting Nature damage to players in front of her." },
    { title = "Poison Stinger", flags = 0, spell = 25748,
      body = "While airborne, Ayamiss looses a poison stinger at a distant player, inflicting heavy Nature damage." },
  },
  [15339] = { -- Ossirian the Unscarred
    { title = "Strength of Ossirian", flags = 2048, spell = 25176,
      body = "Ossirian gains a stacking buff that steadily increases his damage. It can only be stripped by luring him onto one of the Crystals scattered around the arena." },
    { title = "Sand Storm", flags = 32, spell = 10134,
      body = "Tornadoes of sand sweep across the arena, hurling any player they touch high into the air." },
    { title = "Supreme Mode", flags = 16, spell = 0,
      body = "If Ossirian is not weakened at a crystal in time, he enters Supreme Mode and devastates the raid with overwhelming force." },
  },

  -- Temple of Ahn'Qiraj (instance 531) — 40-player raid
  [15263] = { -- The Prophet Skeram
    { title = "True Fulfillment", flags = 32, spell = 785,
      body = "Skeram seizes control of a player's mind, turning them against the raid for a time." },
    { title = "Arcane Explosion", flags = 128, spell = 26192,
      body = "Skeram releases a burst of arcane energy, inflicting heavy Arcane damage to all nearby players." },
    { title = "Earth Shock", flags = 0, spell = 26194,
      body = "Skeram blasts a player with Earth Shock, inflicting Nature damage and interrupting their spellcasting." },
    { title = "Mirror Image", flags = 32, spell = 0,
      body = "At intervals Skeram splits into illusory copies of himself, each able to cast his spells. The images must be cut down to find the true Prophet." },
  },
  [15511] = { -- Silithid Royalty (Kri, Vem, Princess Yauj)
    { title = "Lord Kri: Toxic Volley", flags = 512, spell = 25812,
      body = "Lord Kri looses a volley of toxic spines, inflicting Nature damage and poisoning the raid." },
    { title = "Lord Kri: Poison Cloud", flags = 512, spell = 0,
      body = "When Lord Kri dies, his corpse bursts into a lingering cloud of poison that inflicts heavy Nature damage to any who linger in it." },
    { title = "Vem: Charge & Knock Away", flags = 0, spell = 25778,
      body = "Vem charges across the room and knocks his target away, constantly closing and resetting distance." },
    { title = "Vem's Fury", flags = 2048, spell = 0,
      body = "Should Vem fall before his siblings, Princess Yauj and Lord Kri fly into an enrage for the rest of the fight — Vem must be slain last." },
    { title = "Princess Yauj: Heal", flags = 68, spell = 0,
      body = "Princess Yauj channels powerful heals on her brothers, undoing the raid's progress unless interrupted." },
    { title = "Princess Yauj: Fear", flags = 128, spell = 0,
      body = "Princess Yauj terrifies nearby players, causing them to flee, and summons Yauj Brood on her death." },
  },
  [15516] = { -- Battleguard Sartura
    { title = "Whirlwind", flags = 0, spell = 26083,
      body = "Sartura spins in a relentless whirlwind, inflicting heavy Physical damage to all nearby players while moving unpredictably." },
    { title = "Sundering Cleave", flags = 0, spell = 25174,
      body = "Sartura cleaves all enemies before her, inflicting heavy Physical damage." },
    { title = "Enrage", flags = 2048, spell = 28747,
      body = "Sartura enrages, increasing her attack speed and the damage she deals." },
    { title = "Royal Guards", flags = 32, spell = 0,
      body = "Sartura fights alongside her Royal Guards, who also whirlwind and must be controlled by the raid." },
  },
  [15510] = { -- Fankriss the Unyielding
    { title = "Mortal Wound", flags = 1, spell = 28467,
      body = "Fankriss's strikes inflict Mortal Wounds, a stacking debuff that reduces the healing his target receives." },
    { title = "Entangle", flags = 32, spell = 720,
      body = "Fankriss entangles a random player in webbing, rooting them in place and spawning a Spawn of Fankriss to attack them." },
    { title = "Summon Spawns", flags = 32, spell = 0,
      body = "Fankriss teleports players into his brood and summons Spawns of Fankriss and Vekniss Hatchlings to overwhelm the raid." },
  },
  [15299] = { -- Viscidus
    { title = "Frost Vulnerability", flags = 32, spell = 0,
      body = "Viscidus is vulnerable to Frost. Enough Frost damage slows and then freezes him solid, after which a flurry of melee blows shatters him into Glob oozes." },
    { title = "Poison Bolt Volley", flags = 512, spell = 25991,
      body = "Viscidus hurls a volley of poison bolts, inflicting Nature damage to the raid." },
    { title = "Toxin", flags = 0, spell = 26575,
      body = "Viscidus poisons his attackers with a virulent toxin, inflicting Nature damage over time." },
  },
  [15509] = { -- Princess Huhuran
    { title = "Frenzy", flags = 2048, spell = 23128,
      body = "Huhuran periodically enters a frenzy, increasing her attack and casting speed. It can be soothed by a hunter's Tranquilizing Shot." },
    { title = "Berserk", flags = 2048, spell = 26068,
      body = "Below 30% health, Huhuran goes berserk, unleashing relentless torrents of poison on the entire raid until she falls." },
    { title = "Noxious Poison", flags = 512, spell = 26053,
      body = "Huhuran sprays a noxious poison, inflicting Nature damage over time to those it strikes." },
    { title = "Wyvern Sting", flags = 512, spell = 19386,
      body = "Huhuran stings a player, sending them into a poisoned slumber until the venom runs its course." },
  },
  [15276] = { -- The Twin Emperors (Vek'lor & Vek'nilash)
    { title = "Twin Teleport & Heal", flags = 32, spell = 0,
      body = "The emperors swap positions every thirty seconds and heal one another to full whenever they stand close together — they must be tanked far apart and brought low at the same time." },
    { title = "Vek'lor: Shadow Bolt", flags = 64, spell = 26006,
      body = "Emperor Vek'lor hurls heavy Shadow Bolts at the raid from range." },
    { title = "Vek'lor: Arcane Burst", flags = 128, spell = 568,
      body = "When struck in melee, Emperor Vek'lor releases an Arcane Burst, inflicting heavy Arcane damage and knocking nearby players back — he must be fought at range." },
    { title = "Vek'lor: Blizzard", flags = 0, spell = 26607,
      body = "Emperor Vek'lor conjures a blizzard, inflicting Frost damage over a wide area." },
    { title = "Vek'nilash: Unbalancing Strike", flags = 0, spell = 26613,
      body = "Emperor Vek'nilash delivers an unbalancing strike, inflicting heavy Physical damage and reducing his target's defense." },
    { title = "Vek'nilash: Uppercut", flags = 0, spell = 10966,
      body = "Emperor Vek'nilash launches his target into the air with a mighty uppercut." },
  },
  [15517] = { -- Ouro
    { title = "Sand Blast", flags = 32, spell = 26102,
      body = "Ouro unleashes a sand blast, inflicting massive Nature damage to players in front of him." },
    { title = "Ground Rupture", flags = 0, spell = 26100,
      body = "When Ouro erupts from the sand, the ground ruptures beneath the raid, inflicting Physical damage and knocking players back." },
    { title = "Submerge & Summon", flags = 32, spell = 0,
      body = "Ouro periodically burrows beneath the sand, summoning Dirt Mounds and Ouro Scarabs before erupting back to the surface." },
    { title = "Enrage", flags = 2048, spell = 0,
      body = "If the fight runs long, Ouro enrages, vastly increasing the damage he deals." },
  },
  [15727] = { -- C'Thun
    { title = "Dark Glare", flags = 16, spell = 26029,
      body = "In its eye phase, C'Thun's great eye unleashes a rotating Dark Glare — a sweeping beam that instantly kills anything it touches. Take cover behind the chamber's pillars." },
    { title = "Eye Beam", flags = 0, spell = 26134,
      body = "C'Thun's eye fires green beams that chain between nearby players, inflicting Nature damage." },
    { title = "Flesh Tentacles & Stomach", flags = 32, spell = 0,
      body = "In its body phase, C'Thun swallows players whole into its stomach, where two Flesh Tentacles must be destroyed to leave C'Thun vulnerable. Giant Claw and Eye Tentacles erupt from the body throughout." },
    { title = "Digestive Acid", flags = 0, spell = 26476,
      body = "Players swallowed into C'Thun's stomach are bathed in digestive acid, taking steady Nature damage until they escape." },
  },

  -- Zul'Gurub (instance 309) — 20-player raid
  [14507] = { -- High Priest Venoxis
    { title = "Holy Fire", flags = 192, spell = 15261,
      body = "Venoxis engulfs an enemy in holy fire, inflicting Holy damage instantly and additional Holy damage over time." },
    { title = "Holy Nova", flags = 0, spell = 15237,
      body = "Venoxis releases a burst of holy energy, inflicting Holy damage to all nearby enemies." },
    { title = "Renew", flags = 4, spell = 139,
      body = "Venoxis renews himself, restoring health over time." },
    { title = "Venom Spit", flags = 512, spell = 23849,
      body = "At low health Venoxis transforms into a great cobra, spitting venom that inflicts Nature damage over time and poisoning the raid." },
  },
  [14517] = { -- High Priestess Jeklik
    { title = "Sonic Burst", flags = 128, spell = 23918,
      body = "In bat form, Jeklik looses a sonic burst, inflicting heavy Physical damage and silencing those it strikes." },
    { title = "Charge", flags = 0, spell = 100,
      body = "Jeklik charges a distant player, closing the gap and stunning them briefly." },
    { title = "Psychic Scream", flags = 32, spell = 8122,
      body = "In troll form, Jeklik unleashes a psychic scream, causing nearby players to flee in fear." },
    { title = "Great Heal", flags = 68, spell = 23954,
      body = "Jeklik channels a powerful heal to restore her own health. Interrupt it to keep the pressure on." },
    { title = "Bat Swarm", flags = 32, spell = 0,
      body = "Jeklik summons swarms of Frenzied Bats to harry the raid throughout the fight." },
  },
  [14510] = { -- High Priestess Mar'li
    { title = "Poison Bolt Volley", flags = 512, spell = 24099,
      body = "Mar'li hurls a volley of poison bolts, inflicting Nature damage to the raid." },
    { title = "Spawn of Mar'li", flags = 32, spell = 0,
      body = "Mar'li transforms into a great spider and births swarms of Spawn of Mar'li that hatch and grow into deadly broodlings." },
    { title = "Charge", flags = 0, spell = 100,
      body = "Mar'li charges a distant player, closing the gap and stunning them." },
    { title = "Enrage", flags = 2048, spell = 0,
      body = "As she nears death Mar'li enrages, increasing her attack speed and the damage she deals." },
  },
  [11382] = { -- Bloodlord Mandokir
    { title = "Threatening Gaze", flags = 32, spell = 24314,
      body = "Mandokir fixes a player with a threatening gaze. If they move or act while watched, he charges and strikes them down — stand still until it passes." },
    { title = "Bloodlord's Rage", flags = 2048, spell = 0,
      body = "Each player Mandokir slays empowers him, increasing his size and the damage he deals for the rest of the fight." },
    { title = "Charge", flags = 0, spell = 100,
      body = "Mandokir charges a distant player, closing the gap and striking them for Physical damage." },
    { title = "Whirlwind", flags = 0, spell = 1680,
      body = "Mandokir spins in a whirlwind, inflicting Physical damage to all nearby players." },
    { title = "Ohgan", flags = 32, spell = 0,
      body = "Mandokir rides his devilsaur Ohgan into battle; once Ohgan is slain, the Bloodlord fights on foot." },
  },
  [15114] = { -- Gahz'ranka
    { title = "Massive Geyser", flags = 32, spell = 22421,
      body = "Gahz'ranka summons a massive geyser beneath a player, hurling them high into the air." },
    { title = "Frost Breath", flags = 0, spell = 3131,
      body = "Gahz'ranka breathes a cone of frost, inflicting Frost damage and slowing those it strikes." },
    { title = "Slam", flags = 0, spell = 0,
      body = "Gahz'ranka slams a nearby player, inflicting heavy Physical damage." },
  },
  [14509] = { -- High Priest Thekal
    { title = "Resurrection", flags = 32, spell = 0,
      body = "Thekal and his two High Zealots resurrect one another unless all three are brought to defeat within moments of each other." },
    { title = "Mortal Cleave", flags = 1, spell = 22859,
      body = "Thekal cleaves his target, inflicting heavy Physical damage and reducing the healing they receive." },
    { title = "Silence", flags = 192, spell = 8988,
      body = "Thekal silences nearby spellcasters, preventing them from casting for several seconds." },
    { title = "Blood Lust", flags = 128, spell = 379,
      body = "Thekal works himself into a blood lust, increasing his attack speed." },
    { title = "Frenzy", flags = 2048, spell = 0,
      body = "Revived in tiger form, Thekal enters a frenzy, savaging the raid with rapid, brutal strikes." },
  },
  [14515] = { -- High Priestess Arlokk
    { title = "Mark of Arlokk", flags = 32, spell = 0,
      body = "Arlokk marks a player and vanishes, summoning packs of panthers that fixate on and charge the marked target." },
    { title = "Gouge", flags = 0, spell = 1777,
      body = "Arlokk gouges her target, inflicting Physical damage and incapacitating them briefly." },
    { title = "Whirlwind", flags = 0, spell = 1680,
      body = "Arlokk spins in a whirlwind, inflicting Physical damage to all nearby players." },
    { title = "Shadow Word: Pain", flags = 128, spell = 11639,
      body = "Arlokk afflicts a player with searing pain, inflicting Shadow damage over time." },
  },
  [11380] = { -- Jin'do the Hexxer
    { title = "Brain Wash Totem", flags = 32, spell = 0,
      body = "Jin'do plants a Brain Wash Totem that seizes control of nearby players' minds. Destroy it quickly." },
    { title = "Powerful Hex", flags = 256, spell = 0,
      body = "Jin'do hexes a player, transforming them into a harmless frog and stripping their abilities until the curse is removed." },
    { title = "Shades of Jin'do", flags = 32, spell = 0,
      body = "Jin'do spawns shadowy Shades that pursue and drain the mana of the raid's casters." },
    { title = "Healing Ward", flags = 68, spell = 0,
      body = "Jin'do summons a Healing Ward that rapidly mends him; it must be destroyed to make progress." },
  },
  [14834] = { -- Hakkar
    { title = "Aspects of the Hakkari", flags = 32, spell = 0,
      body = "Until each High Priest is slain, Hakkar wields their aspect — Jeklik's bats, Venoxis' renew, Mar'li's poison, Thekal's frenzy, and Arlokk's gaze. Clearing the priests first strips these powers away." },
    { title = "Blood Siphon", flags = 32, spell = 24323,
      body = "Hakkar siphons the blood of the raid, draining their life to heal himself." },
    { title = "Corrupted Blood", flags = 0, spell = 24328,
      body = "Hakkar infects a player with Corrupted Blood, a virulent affliction that inflicts heavy Shadow damage and spreads to anyone standing nearby." },
    { title = "Cause Insanity", flags = 32, spell = 24327,
      body = "Hakkar drives a player insane, turning them against their allies for a time." },
  },
  [15082] = { -- Gri'lek (Edge of Madness)
    { title = "Charge", flags = 0, spell = 100,
      body = "Gri'lek charges a distant player, closing the gap and striking them for heavy Physical damage." },
    { title = "Ground Tremor", flags = 32, spell = 0,
      body = "Gri'lek smashes the ground, inflicting Physical damage to nearby players and interrupting their spellcasting." },
    { title = "Maul", flags = 0, spell = 0,
      body = "Gri'lek mauls his target with a savage two-handed blow for heavy Physical damage." },
  },
  [15083] = { -- Hazza'rah (Edge of Madness)
    { title = "Sleep", flags = 192, spell = 700,
      body = "Hazza'rah lulls a player into a deep sleep, incapacitating them until they take damage." },
    { title = "Mana Burn", flags = 32, spell = 0,
      body = "Hazza'rah burns away a player's mana, inflicting Shadow damage in proportion to the amount destroyed." },
    { title = "Nightmare Illusions", flags = 32, spell = 0,
      body = "Hazza'rah summons Nightmare Illusions to assail the raid while he hides among them." },
  },
  [15084] = { -- Renataki (Edge of Madness)
    { title = "Thousand Blades", flags = 0, spell = 24649,
      body = "Renataki assaults his target with a thousand blades, inflicting rapid bursts of heavy Physical damage." },
    { title = "Gouge", flags = 0, spell = 1777,
      body = "Renataki gouges his target, inflicting Physical damage and incapacitating them briefly." },
    { title = "Vanish & Ambush", flags = 32, spell = 0,
      body = "Renataki vanishes from sight and reappears behind a random player, ambushing them for massive Physical damage." },
  },
  [15085] = { -- Wushoolay (Edge of Madness)
    { title = "Lightning Cloud", flags = 0, spell = 8293,
      body = "Wushoolay conjures a lightning cloud over the ground, inflicting Nature damage to any player who stands beneath it." },
    { title = "Chain Lightning", flags = 64, spell = 421,
      body = "Wushoolay hurls a bolt of lightning that arcs between nearby players, inflicting Nature damage." },
    { title = "War Stomp", flags = 32, spell = 0,
      body = "Wushoolay stomps the ground, stunning all nearby players for a short time." },
  },

  -- Naxxramas (instance 533) — 40-player raid
  [15956] = { -- Anub'Rekhan
    { title = "Impale", flags = 32, spell = 28783,
      body = "Anub'Rekhan erupts a line of impaling spikes from the ground, inflicting heavy Physical damage and hurling players into the air." },
    { title = "Locust Swarm", flags = 32, spell = 28785,
      body = "Anub'Rekhan surrounds himself with a swarm of locusts, draining the life of nearby players and silencing them. The tank must kite him away until it ends." },
    { title = "Corpse Scarabs", flags = 32, spell = 0,
      body = "Slain Crypt Guards and the boss's own corpse erupt with Corpse Scarabs that swarm the raid." },
  },
  [15953] = { -- Grand Widow Faerlina
    { title = "Poison Bolt Volley", flags = 512, spell = 28796,
      body = "Faerlina looses a volley of poison bolts, inflicting heavy Nature damage to the raid." },
    { title = "Rain of Fire", flags = 0, spell = 28794,
      body = "Faerlina calls down a rain of fire, inflicting Fire damage to all players in the area." },
    { title = "Frenzy", flags = 2048, spell = 0,
      body = "Faerlina enrages, vastly increasing her damage. Mind-controlling one of her Worshippers and unleashing its Widow's Embrace removes the frenzy and silences her." },
  },
  [15952] = { -- Maexxna
    { title = "Web Wrap", flags = 32, spell = 28617,
      body = "Maexxna hurls players against the cavern walls, cocooning them in webbing until they are freed by their allies." },
    { title = "Web Spray", flags = 32, spell = 29484,
      body = "Maexxna sprays the raid with webbing, stunning everyone for several seconds." },
    { title = "Necrotic Poison", flags = 512, spell = 28776,
      body = "Maexxna's bite injects a necrotic poison, sharply reducing the healing her target receives." },
    { title = "Frenzy", flags = 2048, spell = 0,
      body = "Below 30% health, Maexxna enters a frenzy, attacking with greatly increased speed." },
  },
  [15954] = { -- Noth the Plaguebringer
    { title = "Curse of the Plaguebringer", flags = 256, spell = 29213,
      body = "Noth curses the raid; after a few seconds the curse erupts, inflicting heavy Shadow damage to anyone still afflicted." },
    { title = "Cripple", flags = 128, spell = 89,
      body = "Noth cripples a player, slowing their attack and movement speed and weakening their strength." },
    { title = "Blink & Raise Dead", flags = 32, spell = 0,
      body = "Noth blinks free of melee and raises Plagued Champions and Warriors, periodically teleporting to his balcony to send skeletons against the raid." },
  },
  [15936] = { -- Heigan the Unclean
    { title = "Eruption", flags = 16, spell = 17731,
      body = "Heigan channels eruptions of plague that sweep across the floor in sequence. Players must move through the safe zones in rhythm — the infamous Safety Dance — or be killed instantly." },
    { title = "Decrepit Fever", flags = 1024, spell = 29998,
      body = "Heigan afflicts the raid with Decrepit Fever, a disease that inflicts Nature damage over time and reduces maximum health." },
    { title = "Spell Disruption", flags = 32, spell = 0,
      body = "Heigan disrupts the magic around him, sharply increasing the mana cost of the raid's spells." },
  },
  [16011] = { -- Loatheb
    { title = "Necrotic Aura", flags = 32, spell = 0,
      body = "Loatheb radiates a Necrotic Aura that prevents nearly all healing. Healing lands only in brief windows between its pulses, demanding precise cooldown timing." },
    { title = "Inevitable Doom", flags = 16, spell = 29204,
      body = "As the fight wears on, Loatheb inflicts Inevitable Doom at ever-shorter intervals, dealing escalating Shadow damage the healers must survive between Necrotic Aura windows." },
    { title = "Spores", flags = 32, spell = 0,
      body = "Loatheb periodically releases Spores; players spread out to soak them and gain the Fungal Bloom buff needed to maximize their damage." },
  },
  [16061] = { -- Instructor Razuvious
    { title = "Understudies", flags = 32, spell = 0,
      body = "Razuvious can only be held by his Death Knight Understudies, which the raid must mind-control with Obedience Crystals and use to tank him." },
    { title = "Unbalancing Strike", flags = 0, spell = 26613,
      body = "Razuvious delivers an unbalancing strike, inflicting heavy Physical damage and reducing his target's defense." },
    { title = "Disrupting Shout", flags = 0, spell = 29107,
      body = "Razuvious lets out a disrupting shout, inflicting heavy damage to everyone near him." },
  },
  [16060] = { -- Gothik the Harvester
    { title = "Split Realm", flags = 32, spell = 0,
      body = "Gothik divides the raid across a gate into living and dead sides, sending waves of undead that cross over when slain. He cannot be reached until every add falls." },
    { title = "Shadow Bolt", flags = 64, spell = 29317,
      body = "Once he descends to fight, Gothik hurls Shadow Bolts at the raid, inflicting heavy Shadow damage." },
    { title = "Harvest Soul", flags = 0, spell = 28679,
      body = "Gothik harvests the souls of nearby players, inflicting Shadow damage." },
  },
  [16065] = { -- The Four Horsemen
    { title = "Mark of the Horsemen", flags = 32, spell = 0,
      body = "Each Horseman brands their target with a Mark that stacks ever higher and more painful. Tanks and raid must rotate around the four corners of the room to keep their stacks from turning lethal." },
    { title = "Meteor", flags = 32, spell = 0,
      body = "Thane Korth'azz hurls fiery Meteors that inflict massive Fire damage split among nearby players." },
    { title = "Void Zone", flags = 32, spell = 0,
      body = "Lady Blaumeux conjures Void Zones of shadow on the ground that inflict heavy damage to any who stand in them." },
    { title = "Holy Wrath", flags = 0, spell = 28883,
      body = "Sir Zeliek, fighting against his will, looses Holy Wrath and chains of holy lightning across the raid." },
    { title = "Death and Decay", flags = 0, spell = 0,
      body = "Baron Rivendare blankets areas of the floor in Death and Decay, inflicting Shadow damage over time to any who remain." },
  },
  [16028] = { -- Patchwerk
    { title = "Hateful Strike", flags = 33, spell = 28308,
      body = "Patchwerk pounds the highest-health player within melee range with a Hateful Strike for enormous Physical damage. Off-tanks must stack in close to absorb these blows." },
    { title = "Enrage", flags = 2048, spell = 28131,
      body = "Below 5% health, Patchwerk enrages, dramatically increasing his attack speed for a frantic final push." },
  },
  [15931] = { -- Grobbulus
